// Contract Terms - English
$string['term01_english_default'] = 'Furman High School is accredited through the Western Association of Schools and Colleges.  Course requirements and curriculum have been adopted by the Madera Unified School District Board of Education.  Counseling and teaching staff and school resources including, but not limited to, library, all FHS labs, R.O.P. classes, etc., are available to independent study students.';
$string['term02_english_default'] = 'The student will complete the courses listed on the reverse side of the agreement during the semester and report to his/her assigned teacher one-on-one or in small groups.  Alternative methods of reporting must be pre-arranged on a basis of need.  Course objectives will be consistent with MUSD guidelines.  Credit is based upon completion of assigned work and tests.  The maximum number of credits earned per semester is 50, including credits earned through Work Experience and Community Enrichment.';
$string['term03_english_default'] = 'The minimum amount of work to be completed each week is 5 assigned days.  Attendance is based on the amount of work submitted and not on seat time.  Assigned work may be turned in late for academic credit only.  Meetings with the teacher will be scheduled according to the needs of the student. A minimum of one meeting each week is expected so that the teacher may monitor student progress.  The teacher may keep record of grades, credits, attendance on the Student Assignment Card.  The maximum time allowed between the assignment date and the due date shall be six weeks or 30 school days.';
$string['term04_english_default'] = 'There are no excused absences.  Serious illness is the only reason accepted for missed appointments.  Parents are to contact a teacher prior to any missed appointment, to bring in and pick up new assignments.  Students must attend their first meeting with the teacher or they will be dropped immediately.  An SST will be held for any student that fails to comply with the Master Agreement, turns in consistently substandard work, and/or continually misses assigned scheduled meetings.  Any student who falls 15 days behind will be dropped, and an evaluation will be made as to whether the student should continue in independent study or return to a seat time program for his/her best interest.';
$string['term05_english_default'] = 'Student under 18 years old:   The student is to be at home or under the supervision of the parent/guardian during the school day (7:45 a.m. to 3:15 p.m.) and to stay away from other MUSD campuses unless authorized by FHS.';
$string['term06_english_default'] = 'The parent/guardian hereby gives permission for the student to be given standardized academic tests as needed.  ';
$string['term07_english_default'] = 'Students must return all books and take care of any financial obligations to MUSD prior to grades being released or records sent to other schools.';
$string['term08_english_default'] = 'This agreement acknowledges receipt of the Furman High School Parent-Student Handbook.  Students are responsible to familiarize themselves with the information in it.';
$string['term09_english_default'] = 'This agreement informs parent/guardians that independent study is an optional, educational program in which no pupil may be required to participate.  If a student is referred pursuant to Ed Code 48917 or 48915, a regular classroom offering must have also been included as an option for the student.';
$string['term10_english_default'] = 'My continued enrollment in Furman High School will be based upon my compliance with all the terms and conditions of this Master Agreement.';
$string['term11_english_default'] = 'Students must follow all dress code and discipline policies of MUSD.';

// Contract Terms - Spanish
$string['term01_spanish_default'] = 'La Escuela Fuman es acreditada por medio de la Asociación Occidental de Escuelas y Universidades. Requisitos de cursos y currículos han sido adoptados por la Mesa Directiva del Distrito Escolar de Madera. Los consejeros, los maestros y recursos escolares, incluso pero no limitado a, bibliotecas, laboratorios de FHS, clases de ROP, etc., son disponibles para los alumnos de estudios independientes.';
$string['term02_spanish_default'] = 'Durante el semestre, el alumno completará los cursos indicados al reverso y se presentará a su maestro(a) asignado solo o en grupos pequeños. Otros modos de presentarse tendrán que ser arreglados con anticipación. Los objetivos de cursos serán conscientes con las guías de MUSD. Los créditos serán otorgados al completar todas las tareas y exámenes. El máximo de créditos que se pueden obtener en un semestre serán 50, incluyendo los créditos obtenidos por los programas Experiencia de Trabajo o Enriquecimiento de la Comunidad.';
$string['term03_spanish_default'] = 'La mínima cantidad de trabajo completado cada semana es 5 días asignados. La asistencia está basada en la cantidad de tarea entregada y no en el tiempo que se presentan a clases.  Ningún trabajo asignado se aceptará después de un mes de ser asignado a menos que se haya otorgado una aprobación previa. Las juntas con los maestros serán fijadas según las necesidades del estudiante. Se espera lo mínimo de una junta cada semana para que el maestro pueda vigilar el progreso del estudiante. El maestro puede mantener archivos de calificaciones, créditos y asistencia en la tarjeta de tareas.  El tiempo máximo permitido entre la fecha de asignación y la fecha de vencimiento será de seis semanas o 30 días escolares.';
$string['term04_spanish_default'] = 'La única excusa para no asistir a citas será la enfermedad. Los padres deben notificar al maestro antes de fallar una cita para arreglar las tareas. Los estudiantes deben asistir a la primera cita con su maestro o serán expulsados del programa inmediatamente.  Se llevará a cabo un SST para cualquier estudiante que no cumpla con el Acuerdo de Matriculación, que entrega trabajos de calidad inferior constantemente, y/o falten continuamente a las citas programadas.  Cualquier estudiante que falle tres citas o que se retrase por más de 15 días también será expulsado del programa y habrá una evaluación para determinar si el alumno debe seguir con los estudios independientes o regresar a un programa tradicional para su propio beneficio.';
$string['term05_spanish_default'] = 'Estudiantes menores de 18 años de edad: El alumno debe permanecer en casa o bajo la supervisión del padre/guardián durante el día escolar (7:45 am a 3:15 pm) y debe alejarse de otros campos escolares del MUSD a menos que sea autorizado por FHS.';
$string['term06_spanish_default'] = 'Conforme con este acuerdo, el padre/guardián otorga permiso para que el estudiante reciba exámenes académicos normales cuando sea necesario.';
$string['term07_spanish_default'] = 'Los estudiantes deben devolver sus libros y pagar sus cuentas al MUSD antes de que las calificaciones o archivos sean mandados a otras escuelas.';
$string['term08_spanish_default'] = 'Con este acuerdo se da por recibido el Manual para Padres y Alumnos de la Escuela Fuman. El alumno tiene la responsabilidad de familiarizarse con el contenido.';
$string['term09_spanish_default'] = 'Este Folleto les informa a los padres/guardianes que el estudio independiente es un programa educativo opcional en el cual no se requiere que participe ningún estudiante. Si un estudiante es referido de acuerdo con el Código Educativo 48917, un programa regular de salón de clases también debe ser incluido como opción para el alumno.';
$string['term10_spanish_default'] = 'Mi inscripción continua en Furman High School se basará en mi cumplimiento de todos los términos y condiciones de este Acuerdo de Matriculación.';
$string['term11_spanish_default'] = 'Los estudiantes deben observar todas las pólizas del MUSD tocante al vestuario y la disciplina.';